// Exam seating & invigilation (module `exams`, page `seating`). Tenant-scoped.
//
//   ExamSeatPlan   one exam session (a date and start time): the rooms used, who sits on which seat (classes mixed so
//                  neighbours are never from the same class), and the teachers invigilating each room. Generated by
//                  services/examSeating.js with the rules in packages/shared/src/examSeating.js, then edited by hand
//                  (a seat moved by hand is locked and survives the next generation); published for the notice board.
import mongoose from 'mongoose'
import { tenantPlugin } from '../platform/db.js'

const { Schema, model } = mongoose
const ObjectId = Schema.Types.ObjectId
const ymd = { type: String, match: /^\d{4}-\d{2}-\d{2}$/ }
const hhmm = { type: String, match: /^\d{2}:\d{2}$/ }

const layoutSchema = new Schema({ kind: String, perBench: Number, columns: Number, rows: Number, numbering: String }, { _id: false })

const planRoomSchema = new Schema({
  roomId: { type: ObjectId, ref: 'Room', required: true },
  name: String, code: String, kind: String, // copied when the plan is made, so a printout reads the same later
  capacity: Number,
  layout: { type: layoutSchema, default: undefined }, // set for this exam; else the room's home section's seating, else its capacity
  invigilatorIds: { type: [ObjectId], default: [] },
  invigilatorsByHand: { type: Boolean, default: false },
}, { _id: false })

const planSeatSchema = new Schema({
  roomId: { type: ObjectId, required: true },
  seat: { type: String, required: true }, // the seat's label in the room's numbering ("12", "B3")
  order: Number, row: Number, col: Number, pos: Number, across: Number,
  studentId: { type: ObjectId, ref: 'Student', required: true },
  classId: ObjectId,
  locked: { type: Boolean, default: false }, // placed by hand
}, { _id: false })

const planSchema = new Schema({
  examId: { type: ObjectId, ref: 'Exam', required: true },
  date: { ...ymd, required: true },
  startTime: { ...hhmm, required: true },
  endTime: hhmm,
  classIds: { type: [ObjectId], default: [] },
  rules: {
    mix: { type: String, default: 'SEAT' }, // SEAT_MIX
    gap: { type: Boolean, default: false }, // one student per bench of two
    spread: { type: Boolean, default: true }, // share students out over the rooms by size
    fill: { type: String, default: 'ROLL' }, // SEAT_FILL
    perInvigilator: { type: Number, default: 30 },
    maxInvigilators: { type: Number, default: 3 },
  },
  rooms: { type: [planRoomSchema], default: [] },
  seats: { type: [planSeatSchema], default: [] },
  unseated: { type: [ObjectId], default: [] },
  // exam-hall attendance, marked by the invigilators: who didn't come (marks entry starts them as absent)
  absentIds: { type: [ObjectId], default: [] },
  attendance: { type: [new Schema({ roomId: ObjectId, by: String, byId: ObjectId, at: Date }, { _id: false })], default: [] }, // rooms marked
  status: { type: String, default: 'DRAFT' }, // SEAT_PLAN_STATUS
  generatedAt: Date, generatedBy: String,
  publishedAt: Date, publishedBy: String,
  updatedBy: String,
}, { timestamps: true, minimize: false })
planSchema.plugin(tenantPlugin)
planSchema.index({ tenantId: 1, examId: 1, date: 1, startTime: 1 }, { unique: true })
planSchema.index({ tenantId: 1, 'rooms.invigilatorIds': 1, date: 1 })
export const ExamSeatPlan = model('ExamSeatPlan', planSchema, 'exam_seat_plans')
